QUIZ.pki = [
  { q: "Why does the kit keep TLS and code-signing in separate hierarchies?",
    a: ["Browsers require it", "So a leak of one never lets an attacker forge the other", "OpenSSL cannot mix them", "To save certificate fees"], c: 1,
    why: "A TLS key compromise lets someone impersonate a server; a code-signing compromise lets them mint signatures. Keep the blast radius separate." },
  { q: "Fulcio refuses to start with your intermediate CA. Which extension is most likely missing?",
    a: ["subjectAltName", "extendedKeyUsage = codeSigning", "OCSP no-check", "nameConstraints"], c: 1,
    why: "Fulcio's VerifyCertChain requires the issuing certificate in a chain to carry the codeSigning EKU." },
  { q: "In the chain file Fulcio loads, which certificate comes first?",
    a: ["The root", "The issuing (intermediate) certificate", "Any order works", "The TLS certificate"], c: 1,
    why: "Issuing certificate first, root last. cosign's trusted-root builder expects the same order." },
  { q: "Rekor was installed with the chart default signer 'memory'. What happens after a restart?",
    a: ["Nothing", "Rekor signs with a new random key, so clients' trust roots no longer match", "Rekor loses all entries", "Fulcio stops issuing"], c: 1,
    why: "That is why the kit always mounts its own Rekor key (file locally, AWS KMS in production)." },
  { q: "What is the TUF root used for?",
    a: ["Encrypting the registry", "Authorising which keys may publish trusted_root.json updates", "Issuing TLS certificates", "Signing images"], c: 1,
    why: "Clients pin the TUF root once; after that, rotations of Fulcio, Rekor or CT keys arrive as signed TUF updates." },
];

