/* Clickable Rekor entry (abbreviated from the kit's integration test). */
const REKOR_FIELDS = [
  ["logIndex", "1", "Position of this entry in the log. Strictly increasing; gaps never happen in an append-only log."],
  ["logID", "\"b7ed7e9681ffe3f3…\"", "SHA-256 of Rekor's public key. Verifiers use it to pick the right key from trusted_root.json."],
  ["integratedTime", "1792438369", "Unix time Rekor integrated the entry. Must fall inside the certificate's 10-minute validity."],
  ["kind", "\"dsse\"", "Entry type. cosign v3 records signatures as DSSE envelopes; older clients used hashedrekord."],
  ["body.spec.envelopeHash", "\"sha256:38cd32bc…\"", "Hash of the whole DSSE envelope. body.spec.payloadHash is the hash of the signed payload; search Rekor by either, or by the image digest."],
  ["body.spec.signatures[0].verifier", "\"LS0tLS1CRUdJTi…\"", "The signer's Fulcio certificate (base64 PEM). Decode it to see the identity and issuer."],
  ["verification.signedEntryTimestamp", "\"MEUCIQDk…\"", "Rekor's signature over the entry and its time. Proves the log accepted it at integratedTime."],
  ["verification.inclusionProof.hashes", "[\"6d1c…\"]", "Merkle audit path from this entry to the tree root. One hash here because the tree had two entries."],
  ["verification.inclusionProof.checkpoint", "\"rekor.sigstore.local - 7370…\\n2\\nHAAla…\"", "A signed note of tree size and root hash. Comparing checkpoints over time proves nothing was removed."],
];

